import { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import { LANGUAGES } from "./i18n";
import { auth } from "./firebase";
import { onAuthStateChanged, signOut } from "firebase/auth";
import { useSubscription } from "./useSubscription";
import Auth from "./Auth.jsx";
import GlobeMate from "./GlobeMate.jsx";
import Profile from "./Profile.jsx";
import Explore from "./Explore.jsx";
import Chat from "./Chat.jsx";
import Notifications from "./Notifications.jsx";
import Matches from "./Matches.jsx";
import Map from "./Map.jsx";
import Settings from "./Settings.jsx";
import Pricing from "./Pricing.jsx";
import Privacy from "./Privacy.jsx";
import Terms from "./Terms.jsx";
import AdminDashboard, { ADMIN_EMAIL } from "./AdminDashboard.js";


export default function App() {
  const { i18n } = useTranslation();
  const [user, setUser]               = useState(undefined);
  const subscription = useSubscription(user || null);

  // Apply RTL direction whenever language changes
  useEffect(() => {
    const lang = LANGUAGES.find(l => l.code === i18n.resolvedLanguage);
    document.documentElement.dir  = lang?.dir  || "ltr";
    document.documentElement.lang = i18n.resolvedLanguage || "en";
  }, [i18n.resolvedLanguage]);
  const [showAuth, setShowAuth]       = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  const [showExplore, setShowExplore] = useState(false);
  const [showChat, setShowChat]       = useState(false);
  const [showMatches, setShowMatches] = useState(false);
  const [showMap, setShowMap]         = useState(false);
  const [showNotif, setShowNotif]     = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showPricing, setShowPricing] = useState(false);
  const [showPrivacy, setShowPrivacy] = useState(false);
  const [showTerms,   setShowTerms]   = useState(false);
  const [showAdmin,   setShowAdmin]   = useState(false);
  const [notifs, setNotifs]           = useState([]);

  const notifCount  = notifs.filter(n => !n.read).length;
  const markAllRead = () => setNotifs(prev => prev.map(n => ({ ...n, read: true })));
  const markRead    = (id) => setNotifs(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));

  useEffect(() => {
    const unsub = onAuthStateChanged(auth, (u) => {
      setUser(u);
      // Auth closes only when onAuthSuccess() is called explicitly —
      // never on auth-state change, so the phone-verification step
      // isn't skipped when Firebase creates the account mid-flow.
    });
    return () => unsub();
  }, []);

  // initialise history state so browser back has a baseline
  useEffect(() => {
    window.history.replaceState({ screen: "home" }, "");
  }, []);

  // browser/mobile back button
  useEffect(() => {
    const handlePop = (e) => {
      const screen = e.state?.screen || "home";
      setShowProfile(false);
      setShowExplore(false);
      setShowChat(false);
      setShowMatches(false);
      setShowMap(false);
      setShowNotif(false);
      setShowSettings(false);
      setShowPricing(false);
      setShowPrivacy(false);
      setShowTerms(false);
      setShowAdmin(false);
      if (screen === "profile") setShowProfile(true);
      else if (screen === "explore") setShowExplore(true);
      else if (screen === "chat") setShowChat(true);
      else if (screen === "matches") setShowMatches(true);
      else if (screen === "map") setShowMap(true);
      else if (screen === "notif") setShowNotif(true);
      else if (screen === "settings") setShowSettings(true);
      else if (screen === "pricing") setShowPricing(true);
      else if (screen === "privacy") setShowPrivacy(true);
      else if (screen === "terms")   setShowTerms(true);
      else if (screen === "admin")   setShowAdmin(true);
    };
    window.addEventListener("popstate", handlePop);
    return () => window.removeEventListener("popstate", handlePop);
  }, []);

  if (user === undefined) {
    return (
      <div style={{
        minHeight: "100vh",
        background: "#0a0905",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "'DM Sans', sans-serif",
        color: "rgba(245,240,232,0.4)",
        fontSize: "0.85rem",
        letterSpacing: "0.15em",
        textTransform: "uppercase",
      }}>
        Loading…
      </div>
    );
  }

  if (showAuth) {
    return <Auth onAuthSuccess={() => setShowAuth(false)} />;
  }

  // navigate to a screen and push history state
  const goTo = (screen) => {
    window.history.pushState({ screen }, "");
    setShowProfile(false);
    setShowExplore(false);
    setShowChat(false);
    setShowMatches(false);
    setShowMap(false);
    setShowNotif(false);
    setShowSettings(false);
    setShowPricing(false);
    setShowPrivacy(false);
    setShowTerms(false);
    setShowAdmin(false);
    if (screen === "profile") setShowProfile(true);
    else if (screen === "explore") setShowExplore(true);
    else if (screen === "chat") setShowChat(true);
    else if (screen === "matches") setShowMatches(true);
    else if (screen === "map") setShowMap(true);
    else if (screen === "notif") setShowNotif(true);
    else if (screen === "settings") setShowSettings(true);
    else if (screen === "pricing") setShowPricing(true);
    else if (screen === "privacy") setShowPrivacy(true);
    else if (screen === "terms")   setShowTerms(true);
    else if (screen === "admin")   setShowAdmin(true);
  };

  const isAdmin = user?.email === ADMIN_EMAIL;

  const nav = {
    onNotif:   () => goTo("notif"),
    notifCount,
    onProfile:  () => goTo("profile"),
    onExplore:  () => goTo("explore"),
    onChat:     () => goTo("chat"),
    onMatches:  () => goTo("matches"),
    onMap:      () => goTo("map"),
    onSettings: () => goTo("settings"),
    onPricing:  () => goTo("pricing"),
    onPrivacy:  () => goTo("privacy"),
    onTerms:    () => goTo("terms"),
    onSignOut:  () => signOut(auth),
    ...(isAdmin ? { onAdmin: () => goTo("admin") } : {}),
  };

  if (showAdmin && user && isAdmin) {
    return <AdminDashboard user={user} onBack={() => window.history.back()} />;
  }

  if (showPrivacy) {
    return <Privacy onBack={() => window.history.back()} />;
  }

  if (showTerms) {
    return <Terms onBack={() => window.history.back()} />;
  }

  if (showPricing) {
    return <Pricing user={user} onBack={() => window.history.back()} subscription={subscription} {...nav} />;
  }

  if (showSettings && user) {
    return <Settings user={user} onBack={() => window.history.back()} {...nav} />;
  }

  if (showNotif && user) {
    return (
      <Notifications
        notifications={notifs}
        onBack={() => window.history.back()}
        onMarkAllRead={markAllRead}
        onMarkRead={markRead}
        {...nav}
      />
    );
  }

  if (showProfile && user) {
    return <Profile user={user} onBack={() => window.history.back()} subscription={subscription} {...nav} />;
  }

  if (showExplore) {
    return <Explore user={user} onBack={() => window.history.back()} {...nav} />;
  }

  if (showChat && user) {
    return <Chat user={user} onBack={() => window.history.back()} {...nav} />;
  }

  if (showMatches && user) {
    return <Matches user={user} onBack={() => window.history.back()} {...nav} />;
  }

  if (showMap && user) {
    return <Map user={user} onBack={() => window.history.back()} {...nav} />;
  }

  return (
    <GlobeMate
      user={user}
      onSignIn={() => setShowAuth(true)}
      {...nav}
    />
  );
}
